declare(strict_types=1);
require_once __DIR__.'/../../lib/helpers.php';send_cors_headers();if(($_SERVER['REQUEST_METHOD']??'')!=='POST')json_response(405,['success'=>false,'message'=>'Method not allowed.']);$body=get_json_body();$email=strtolower(trim((string)($body['email']??'')));$code=preg_replace('/\D+/','',(string)($body['code']??''));if(!is_valid_email($email)||strlen($code)!==6)json_response(422,['success'=>false,'message'=>'Enter a valid email and six-digit code.']);if(rate_limit('influencer-verify|'.$email.'|'.request_ip(),10,900))json_response(429,['success'=>false,'message'=>'Too many verification attempts.']);$db=get_db();$stmt=$db->prepare('SELECT * FROM influencers WHERE email=:email');$stmt->execute(['email'=>$email]);$creator=$stmt->fetch();if(!$creator||$creator['email_verified'])json_response(400,['success'=>false,'message'=>'Code is invalid or no longer required.']);if((int)$creator['otp_attempts']>=5||strtotime((string)$creator['otp_expires_at'])<time())json_response(410,['success'=>false,'message'=>'Code expired.']);if(!password_verify($code,(string)$creator['otp_hash'])){$db->prepare('UPDATE influencers SET otp_attempts=otp_attempts+1 WHERE id=:id')->execute(['id'=>$creator['id']]);json_response(400,['success'=>false,'message'=>'Verification code is incorrect.']);}$db->prepare('UPDATE influencers SET email_verified=1,otp_hash=NULL,otp_expires_at=NULL,otp_attempts=0,status="application_draft",updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$creator['id']]);$session=create_auth_session('influencer',$creator['id']);json_response(200,['success'=>true,'message'=>'Email verified. Complete your creator application.','csrf_token'=>$session['csrf_token'],'influencer'=>['id'=>$creator['id'],'full_name'=>$creator['full_name'],'email'=>$creator['email'],'handle'=>$creator['handle'],'status'=>'application_draft']]);
